import * as THREE from './three.module.js';
import {block,beam,finish} from './venue-tools.js';
function random(seed=311){return ()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};}
function canvasTexture(w,h,draw){if(typeof document==='undefined')return null;const c=document.createElement('canvas');c.width=w;c.height=h;draw(c.getContext('2d'),w,h);const map=new THREE.CanvasTexture(c);map.colorSpace=THREE.SRGBColorSpace;return map;}
function asphalt(){return canvasTexture(1024,1536,(c,w,h)=>{const rnd=random();c.fillStyle='#444b43';c.fillRect(0,0,w,h);c.fillStyle='#4d605649';c.fillRect(45,50,w-90,h-100);c.fillStyle='#755c4a55';for(const y of [55,h-410])c.fillRect(w/2-135,y,270,355);c.strokeStyle='#c0b88c99';c.lineWidth=5;c.strokeRect(45,50,w-90,h-100);c.beginPath();c.moveTo(45,h/2);c.lineTo(w-45,h/2);c.stroke();c.beginPath();c.arc(w/2,h/2,105,0,Math.PI*2);c.stroke();for(const side of [-1,1]){const y=side<0?55:h-55;c.strokeRect(w/2-135,side<0?y:y-355,270,355);c.beginPath();c.arc(w/2,side<0?y+355:y-355,95,0,Math.PI*2);c.stroke();c.beginPath();c.arc(w/2,side<0?y+65:y-65,360,side<0?0:Math.PI,side<0?Math.PI:2*Math.PI);c.stroke();}
 for(let i=0;i<27000;i++){c.fillStyle=i%2?'#b7b99c13':'#17251d20';c.fillRect(rnd()*w,rnd()*h,1+rnd()*6,1+rnd()*3);}for(let i=0;i<35;i++){let x=rnd()*w,y=rnd()*h;c.strokeStyle='#1c2a23aa';c.lineWidth=1+rnd()*2;c.beginPath();c.moveTo(x,y);for(let j=0;j<9;j++){x+=(rnd()-.5)*40;y+=10+rnd()*20;c.lineTo(x,y);}c.stroke();}for(let i=0;i<650;i++){c.fillStyle='#3b463ba0';c.fillRect(rnd()*w,rnd()*h,2+rnd()*22,1+rnd()*5);}});}
function rustTexture(base,seed){return canvasTexture(512,256,(c,w,h)=>{const rnd=random(seed);c.fillStyle=base;c.fillRect(0,0,w,h);for(let i=0;i<1800;i++){c.fillStyle=['#75452c99','#412e22aa','#9b704b77','#aaa28a22'][i%4];c.beginPath();c.ellipse(rnd()*w,rnd()*h,1+rnd()*13,.5+rnd()*7,rnd()*Math.PI,0,Math.PI*2);c.fill();}c.strokeStyle='#bbb9a044';c.lineWidth=.6;for(let i=0;i<90;i++){const x=rnd()*w,y=rnd()*h;c.beginPath();c.moveTo(x,y);c.lineTo(x+5+rnd()*35,y+2);c.stroke();}});}
function car(base,seed){const g=new THREE.Group();g.userData.rustyParkedCar=true;const paint=finish('#c2beb0',{map:rustTexture(base,seed),roughness:.93,metalness:.18}),rubber=finish('#222824'),metal=finish('#777c71',{metalness:.45}),glass=finish('#283b3d',{roughness:.32,metalness:.15}),dark=finish('#27322c'),rust=finish('#68452f');
 const outline=new THREE.Shape();outline.moveTo(-.72,-2.18);outline.lineTo(.72,-2.18);outline.quadraticCurveTo(.92,-2.18,.94,-1.92);outline.lineTo(.94,1.9);outline.quadraticCurveTo(.91,2.18,.7,2.18);outline.lineTo(-.7,2.18);outline.quadraticCurveTo(-.94,2.18,-.94,1.9);outline.lineTo(-.94,-1.92);outline.quadraticCurveTo(-.92,-2.18,-.72,-2.18);const body=new THREE.Mesh(new THREE.ExtrudeGeometry(outline,{depth:.49,bevelEnabled:true,bevelSize:.055,bevelThickness:.055,bevelSegments:2,steps:1,curveSegments:6}),paint);body.rotation.x=-Math.PI/2;body.position.y=.36;g.add(body);
 const roof=block(g,1.26,.09,1.28,0,1.42,-.12,paint);const faces=[[[.87,.85,.94],[-.87,.85,.94],[-.61,1.38,.50],[.61,1.38,.50]],[[-.87,.85,-1.20],[.87,.85,-1.20],[.61,1.38,-.76],[-.61,1.38,-.76]],[[.87,.85,-1.20],[.87,.85,.94],[.61,1.38,.50],[.61,1.38,-.76]],[[-.87,.85,.94],[-.87,.85,-1.20],[-.61,1.38,-.76],[-.61,1.38,.50]]];
 for(const p of faces){const positions=[...p[0],...p[1],...p[2],...p[0],...p[2],...p[3]],geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));geo.computeVertexNormals();const m=glass.clone();m.side=THREE.DoubleSide;g.add(new THREE.Mesh(geo,m));for(let i=0;i<4;i++)beam(g,p[i],p[(i+1)%4],.026,paint);}
 for(const side of [-1,1]){beam(g,[side*.87,.85,-.15],[side*.61,1.38,-.15],.025,paint);block(g,.06,.035,.20,side*.965,.72,.06,metal);block(g,1.7,.10,.16,0,.42,side*2.22,metal);for(const x of [-.59,.59])block(g,.38,.13,.035,x,.70,side*2.19,finish(side>0?'#b6b49a':'#713b32'));}
 for(const x of [-.94,.94])for(const z of [-1.36,1.37]){const wheel=new THREE.Mesh(new THREE.CylinderGeometry(.33,.33,.21,18),rubber);wheel.rotation.z=Math.PI/2;wheel.position.set(x,.34,z);g.add(wheel);const rim=new THREE.Mesh(new THREE.CylinderGeometry(.17,.17,.225,14),seed%2?rust:metal);rim.rotation.z=Math.PI/2;rim.position.copy(wheel.position);g.add(rim);}
 block(g,1.08,.13,.035,0,.54,2.245,dark);for(let n=0;n<7;n++)block(g,.035,.11,.025,-.45+n*.15,.54,2.27,metal);block(g,.42,.14,.02,0,.39,-2.31,finish('#99967e'));const hood=block(g,1.45,.025,.90,0,.90,1.49,paint);hood.rotation.x=seed%2?.025:-.02;beam(g,[-.80,.84,.98],[-.69,1.22,.62],.009,metal);beam(g,[.22,.91,.90],[-.13,1.10,.74],.007,metal);
 return g;
}
function hoop(group,x,z,side){const metal=finish('#675c47',{metalness:.35}),board=finish('#a3a38b'),rimMat=finish('#874f30');beam(group,[x,-.25,z+side*.75],[x,3.65,z+side*.75],.065,metal);beam(group,[x,3.45,z+side*.75],[x,3.35,z],.045,metal);block(group,1.8,1.05,.10,x,3.35,z,board);block(group,.63,.045,.015,x,3.29,z-side*.061,metal);for(const dx of [-.31,.31])block(group,.035,.40,.015,x+dx,3.09,z-side*.061,metal);block(group,.63,.035,.015,x,2.89,z-side*.061,metal);const rim=new THREE.Mesh(new THREE.TorusGeometry(.23,.018,6,22),rimMat);rim.rotation.x=Math.PI/2;rim.position.set(x,2.91,z-side*.32);rim.userData.basketballHoop=true;group.add(rim);for(let i=0;i<9;i++){const a=i*Math.PI*2/9;beam(group,[x+Math.cos(a)*.22,2.90,z-side*.32+Math.sin(a)*.22],[x+Math.cos(a+.22)*.13,2.52-(i%3)*.035,z-side*.32+Math.sin(a+.22)*.13],.005,finish('#7b8071'));}beam(group,[x-.72,3.73,z-side*.062],[x-.25,3.22,z-side*.062],.006,metal);}
export function buildBasketballLot(){const group=new THREE.Group();group.userData.basketballLot=true;const court=new THREE.Mesh(new THREE.PlaneGeometry(20,29),finish('#c4c9b3',{map:asphalt(),roughness:1}));court.rotation.x=-Math.PI/2;court.position.set(20,-.28,0);court.userData.basketballCourt=true;group.add(court);hoop(group,20,12.7,1);hoop(group,20,-12.7,-1);
 for(const [i,x,z,yaw]of [[0,9,17,.2],[1,33,11,-.18],[2,34,-5,.1],[3,29,-19,1.35],[4,13,-19,-.5]]){const vehicle=car(['#636d5d','#69777b','#887a5c','#756459','#4d665f'][i],141+i);vehicle.position.set(x,-.3,z);vehicle.rotation.y=yaw;vehicle.rotation.z=i===2?.035:0;group.add(vehicle);}
 const rnd=random(46),positions=[];for(let n=0;n<220;n++){const x=n%3?8+rnd()*28:30+rnd()*5,z=(rnd()-.5)*40,size=.025+rnd()*.09;positions.push(x,-.265,z,x+size,-.263,z+.025,x+size*.3,-.262,z+size*.7);}const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));geo.computeVertexNormals();const shards=new THREE.Mesh(geo,new THREE.MeshBasicMaterial({color:'#9dbbb3',transparent:true,opacity:.55,side:THREE.DoubleSide,depthWrite:false}));shards.userData.brokenGlass=true;group.add(shards);
 const iron=finish('#5b685e');for(let z=-17;z<=17;z+=4.25)beam(group,[32,-.3,z],[32,3.1,z],.032,iron);const wire=[];for(let z=-18;z<18;z+=.24)for(const direction of [-1,1]){wire.push(32,.1,z,32,3,z+direction*2.9);}const fenceGeo=new THREE.BufferGeometry();fenceGeo.setAttribute('position',new THREE.Float32BufferAttribute(wire,3));group.add(new THREE.LineSegments(fenceGeo,new THREE.LineBasicMaterial({color:'#718274',transparent:true,opacity:.45})));
 return group;
}
